namespace PrIMA.Detectors.Sdk;

/// <summary>
/// Telemetry inspection report generated by a detector probe.
/// </summary>
public sealed record TelemetryReport
{
    public DateTime InspectionTimestampUtc { get; init; } = DateTime.UtcNow;
    public string Outcome { get; init; } = TelemetryOutcome.Passed;
    public IReadOnlyList<FindingItem> Findings { get; init; } = Array.Empty<FindingItem>();
    public int ExecutionDurationMs { get; init; }
    public string? TraceString { get; init; }
    public string? ErrorMessage { get; init; }

    public static TelemetryReport Passed(int durationMs = 0, string? traceString = null) =>
        new()
        {
            InspectionTimestampUtc = DateTime.UtcNow,
            Outcome = TelemetryOutcome.Passed,
            Findings = Array.Empty<FindingItem>(),
            ExecutionDurationMs = durationMs,
            TraceString = traceString
        };

    public static TelemetryReport FindingDiscovered(
        IReadOnlyList<FindingItem> findings,
        int durationMs = 0,
        string? traceString = null) =>
        new()
        {
            InspectionTimestampUtc = DateTime.UtcNow,
            Outcome = TelemetryOutcome.FindingDiscovered,
            Findings = findings ?? Array.Empty<FindingItem>(),
            ExecutionDurationMs = durationMs,
            TraceString = traceString
        };

    public static TelemetryReport ExecutionFailed(
        string errorMessage,
        string? traceString = null,
        int durationMs = 0) =>
        new()
        {
            InspectionTimestampUtc = DateTime.UtcNow,
            Outcome = TelemetryOutcome.ExecutionFailed,
            Findings = Array.Empty<FindingItem>(),
            ExecutionDurationMs = durationMs,
            ErrorMessage = errorMessage,
            TraceString = traceString
        };
}
